int main() {
    int N;
    scanf("%d", &N);

    int dario = 0, xerxes = 0;

    for (int i = 0; i < N; i++) {
        int D, X;
        scanf("%d %d", &D, &X);

        if (D == (X + 1) % 5 || D == (X + 2) % 5) {
            xerxes++;
        } else {
            dario++;
        }
    }

    if (dario > xerxes) {
        printf("dario\n");
    } else {
        printf("xerxes\n");
    }

    return 0;
}
